            'custom_sections' => '[{\"title\":{\"en\":\"About Faculty\",\"km\":\"\\u17a2\\u17c6\\u1796\\u17b8\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\"},\"content\":{\"en\":\"<p class=\\\"ql-align-justify\\\">The Faculty of Digital Industries (FDI) at the Digital University of Cambodia (DUC) is a leading academic center dedicated to fostering excellence in technology, creativity, and digital business. The faculty operates four specialized departments designed to meet the demands of the modern digital economy:<\\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Department of Graphic Design:<\\\/strong> Cultivating creative visual communication and UI\\\/UX engineering.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Department of Digital Marketing<\\\/strong>: Empowering students with data-driven and strategic online marketing methodologies.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Department of Social Media<\\\/strong>: Developing digital content creation, media management, and online communication strategies.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Department of Information Technology<\\\/strong>: Focusing on full-stack software development, web programming, and network infrastructure.<\\\/li><\\\/ol><p><br><\\\/p>\",\"km\":\"<p>\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u17a7\\u179f\\u17d2\\u179f\\u17b6\\u17a0\\u1780\\u1798\\u17d2\\u1798\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b (FDI) \\u1793\\u17c3\\u179f\\u17b6\\u1780\\u179b\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u1780\\u1798\\u17d2\\u1796\\u17bb\\u1787\\u17b6 (DUC) \\u1782\\u17ba\\u1787\\u17b6\\u1798\\u1787\\u17d2\\u1788\\u1798\\u178e\\u17d2\\u178c\\u179b\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u1792\\u17b7\\u1780\\u17b6\\u179a\\u1788\\u17b6\\u1793\\u1798\\u17bb\\u1781\\u1782\\u17c1\\u1798\\u17bd\\u1799\\u178a\\u17c2\\u179b\\u1795\\u17d2\\u178f\\u17c4\\u178f\\u179b\\u17be\\u1780\\u17b6\\u179a\\u179b\\u17be\\u1780\\u1780\\u1798\\u17d2\\u1796\\u179f\\u17cb\\u17a7\\u178f\\u17d2\\u178a\\u1798\\u1797\\u17b6\\u1796\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6 \\u1782\\u17c6\\u1793\\u17b7\\u178f\\u1785\\u17d2\\u1793\\u17c3\\u1794\\u17d2\\u179a\\u178c\\u17b7\\u178f \\u1793\\u17b7\\u1784\\u17a2\\u17b6\\u1787\\u17b8\\u179c\\u1780\\u1798\\u17d2\\u1798\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u17d4 \\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u178a\\u17c6\\u178e\\u17be\\u179a\\u1780\\u17b6\\u179a\\u178a\\u17c1\\u1794\\u17c9\\u17b6\\u178f\\u17ba\\u1798\\u17c9\\u1784\\u17cb\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u1785\\u17c6\\u1793\\u17bd\\u1793\\u1794\\u17bd\\u1793 \\u178a\\u17c2\\u179b\\u178f\\u17d2\\u179a\\u17bc\\u179c\\u1794\\u17b6\\u1793\\u179a\\u1785\\u1793\\u17b6\\u17a1\\u17be\\u1784\\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u1786\\u17d2\\u179b\\u17be\\u1799\\u178f\\u1794\\u1791\\u17c5\\u1793\\u17b9\\u1784\\u178f\\u1798\\u17d2\\u179a\\u17bc\\u179c\\u1780\\u17b6\\u179a\\u1793\\u17c3\\u179f\\u17c1\\u178a\\u17d2\\u178b\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u1791\\u17c6\\u1793\\u17be\\u1794\\u17d6<\\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>\\u178a\\u17c1\\u1794\\u17c9\\u17b6\\u178f\\u17ba\\u1798\\u17c9\\u1784\\u17cb\\u1780\\u17d2\\u179a\\u17b6\\u17a0\\u17d2\\u179c\\u17b7\\u1780\\u178c\\u17b8\\u17a0\\u17d2\\u179f\\u17b6\\u1789 (Department of Graphic Design):<\\\/strong> \\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u179b\\u1780\\u17b6\\u179a\\u1791\\u17c6\\u1793\\u17b6\\u1780\\u17cb\\u1791\\u17c6\\u1793\\u1784\\u1791\\u179f\\u17d2\\u179f\\u1793\\u17b8\\u1799\\u1797\\u17b6\\u1796\\u1785\\u17d2\\u1793\\u17c3\\u1794\\u17d2\\u179a\\u178c\\u17b7\\u178f \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u179a\\u1785\\u1793\\u17b6 UI\\\/UX (UI\\\/UX engineering)\\u17d4<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>\\u178a\\u17c1\\u1794\\u17c9\\u17b6\\u178f\\u17ba\\u1798\\u17c9\\u1784\\u17cb\\u1791\\u17b8\\u1795\\u17d2\\u179f\\u17b6\\u179a\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b (Department of Digital Marketing):<\\\/strong> \\u1795\\u17d2\\u178f\\u179b\\u17cb\\u1787\\u17bc\\u1793\\u1793\\u17b7\\u179f\\u17d2\\u179f\\u17b7\\u178f\\u1793\\u17bc\\u179c\\u179c\\u17b7\\u1792\\u17b8\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1791\\u17b8\\u1795\\u17d2\\u179f\\u17b6\\u179a\\u17a2\\u1793\\u17a1\\u17b6\\u1789\\u178f\\u17b6\\u1798\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1791\\u17b7\\u1793\\u17d2\\u1793\\u1793\\u17d0\\u1799 (data-driven) \\u1793\\u17b7\\u1784\\u1799\\u17bb\\u1791\\u17d2\\u1792\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1785\\u17d2\\u1794\\u17b6\\u179f\\u17cb\\u179b\\u17b6\\u179f\\u17cb\\u17d4<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>\\u178a\\u17c1\\u1794\\u17c9\\u17b6\\u178f\\u17ba\\u1798\\u17c9\\u1784\\u17cb\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1795\\u17d2\\u179f\\u1796\\u17d2\\u179c\\u1795\\u17d2\\u179f\\u17b6\\u1799\\u179f\\u1784\\u17d2\\u1782\\u1798 (Department of Social Media):<\\\/strong> \\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1780\\u17b6\\u179a\\u1794\\u1784\\u17d2\\u1780\\u17be\\u178f\\u1798\\u17b6\\u178f\\u17b7\\u1780\\u17b6\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u1780\\u17b6\\u179a\\u1782\\u17d2\\u179a\\u1794\\u17cb\\u1782\\u17d2\\u179a\\u1784\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1795\\u17d2\\u179f\\u1796\\u17d2\\u179c\\u1795\\u17d2\\u179f\\u17b6\\u1799 \\u1793\\u17b7\\u1784\\u1799\\u17bb\\u1791\\u17d2\\u1792\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1791\\u17c6\\u1793\\u17b6\\u1780\\u17cb\\u1791\\u17c6\\u1793\\u1784\\u178f\\u17b6\\u1798\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u17a2\\u1793\\u17a1\\u17b6\\u1789\\u17d4<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>\\u178a\\u17c1\\u1794\\u17c9\\u17b6\\u178f\\u17ba\\u1798\\u17c9\\u1784\\u17cb\\u1796\\u17d0\\u178f\\u17cc\\u1798\\u17b6\\u1793\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6 (Department of Information Technology):<\\\/strong> \\u1795\\u17d2\\u178f\\u17c4\\u178f\\u179b\\u17be\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u179f\\u17bc\\u17a0\\u17d2\\u179c\\u179c\\u17c2\\u179a\\u1796\\u17c1\\u1789\\u179b\\u17c1\\u1789 (Full-stack software development) \\u1780\\u17b6\\u179a\\u179f\\u179a\\u179f\\u17c1\\u179a\\u1780\\u1798\\u17d2\\u1798\\u179c\\u17b7\\u1792\\u17b8\\u179c\\u17c1\\u1794\\u179f\\u17b6\\u1799 \\u1793\\u17b7\\u1784\\u17a0\\u17c1\\u178a\\u17d2\\u178b\\u17b6\\u179a\\u1785\\u1793\\u17b6\\u179f\\u1798\\u17d2\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u1789\\u1791\\u17c6\\u1793\\u17b6\\u1780\\u17cb\\u1791\\u17c6\\u1793\\u1784\\u17d4<\\\/li><\\\/ol>\"}},{\"title\":{\"en\":\"Mission\",\"km\":\"\\u1794\\u17c1\\u179f\\u1780\\u1780\\u1798\\u17d2\\u1798\"},\"content\":{\"en\":\"<p>The Faculty of Digital Industries is dedicated to the following missions:<\\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>To educate and train students to attain high-level knowledge, advanced technical skills, and professional ethics in the digital technology domain.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>To continuously develop and update curricula to remain synchronized with modern tech advancements and dynamic job market demands.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>To promote and elevate academic research, technological innovation, and practical digital projects.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>To strengthen the capacity and pedagogical competence of faculty members and technical staff through continuous professional development<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>To foster and expand strategic collaborations with the IT industry sector and relevant ecosystem stakeholders.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>To implement and enhance robust internal educational quality assurance systems to ensure academic excellence.<\\\/li><\\\/ol><p><br><\\\/p>\",\"km\":\"<p>\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u17a7\\u179f\\u17d2\\u179f\\u17b6\\u17a0\\u1780\\u1798\\u17d2\\u1798\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u1798\\u17b6\\u1793\\u1794\\u17c1\\u179f\\u1780\\u1780\\u1798\\u17d2\\u1798\\u178a\\u17bc\\u1785\\u1781\\u17b6\\u1784\\u1780\\u17d2\\u179a\\u17c4\\u1798\\u17d6<\\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>\\u17a2\\u1794\\u17cb\\u179a\\u17c6 \\u1793\\u17b7\\u1784\\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u179b\\u1793\\u17b7\\u179f\\u17d2\\u179f\\u17b7\\u178f\\u17b1\\u17d2\\u1799\\u1791\\u1791\\u17bd\\u179b\\u1794\\u17b6\\u1793\\u1785\\u17c6\\u178e\\u17c1\\u17c7\\u178a\\u17b9\\u1784\\u1780\\u1798\\u17d2\\u179a\\u17b7\\u178f