\\u17d2\\u179a\\u17b6\\u179c\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u1792\\u17b7\\u1780\\u17b6\\u179a \\u1780\\u17b6\\u179a\\u1794\\u1784\\u17d2\\u1780\\u17be\\u178f\\u1790\\u17d2\\u1798\\u17b8\\u1795\\u17d2\\u1793\\u17c2\\u1780\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6 \\u1793\\u17b7\\u1784\\u1782\\u1798\\u17d2\\u179a\\u17c4\\u1784\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u17a2\\u1793\\u17bb\\u179c\\u178f\\u17d2\\u178f\\u1787\\u17b6\\u1780\\u17cb\\u179f\\u17d2\\u178f\\u17c2\\u1784\\u17d4<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>\\u1796\\u1784\\u17d2\\u179a\\u17b9\\u1784\\u179f\\u1798\\u178f\\u17d2\\u1790\\u1797\\u17b6\\u1796 \\u1793\\u17b7\\u1784\\u1782\\u179a\\u17bb\\u1780\\u17c4\\u179f\\u179b\\u17d2\\u1799\\u179a\\u1794\\u179f\\u17cb\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u17b6\\u1785\\u17b6\\u179a\\u17d2\\u1799 \\u1793\\u17b7\\u1784\\u1794\\u17bb\\u1782\\u17d2\\u1782\\u179b\\u17b7\\u1780\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u1791\\u17c1\\u179f \\u178f\\u17b6\\u1798\\u179a\\u1799\\u17c8\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u179c\\u17b7\\u1787\\u17d2\\u1787\\u17b6\\u1787\\u17b8\\u179c\\u17c8\\u1787\\u17b6\\u1794\\u17d2\\u179a\\u1785\\u17b6\\u17c6\\u17d4<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>\\u1794\\u1784\\u17d2\\u1780\\u17be\\u178f \\u1793\\u17b7\\u1784\\u1796\\u1784\\u17d2\\u179a\\u17b8\\u1780\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u179f\\u17a0\\u1794\\u17d2\\u179a\\u178f\\u17b7\\u1794\\u178f\\u17d2\\u178f\\u17b7\\u1780\\u17b6\\u179a\\u1799\\u17bb\\u1791\\u17d2\\u1792\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1787\\u17b6\\u1798\\u17bd\\u1799\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u17a7\\u179f\\u17d2\\u179f\\u17b6\\u17a0\\u1780\\u1798\\u17d2\\u1798 IT \\u1793\\u17b7\\u1784\\u1797\\u17b6\\u1782\\u17b8\\u1796\\u17b6\\u1780\\u17cb\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u17a2\\u17c1\\u1780\\u17bc\\u17a1\\u17bc\\u179f\\u17ca\\u17b8\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u17d4<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>\\u17a2\\u1793\\u17bb\\u179c\\u178f\\u17d2\\u178f \\u1793\\u17b7\\u1784\\u1796\\u1784\\u17d2\\u179a\\u17b9\\u1784\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796\\u1780\\u17b6\\u179a\\u1792\\u17b6\\u1793\\u17b6\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796\\u17a2\\u1794\\u17cb\\u179a\\u17c6\\u1795\\u17d2\\u1791\\u17c3\\u1780\\u17d2\\u1793\\u17bb\\u1784 \\u178a\\u17be\\u1798\\u17b8\\u17d2\\u1794\\u1792\\u17b6\\u1793\\u17b6\\u1794\\u17b6\\u1793\\u1793\\u17bc\\u179c\\u17a7\\u178f\\u17d2\\u178a\\u1798\\u1797\\u17b6\\u1796\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u17d4<\\\/li><\\\/ol>\"}},{\"title\":{\"en\":\"Vision\",\"km\":\"\\u1785\\u1780\\u17d2\\u1781\\u17bb\\u179c\\u17b7\\u179f\\u17d0\\u1799\"},\"content\":{\"en\":\"<p class=\\\"ql-align-justify\\\">To become a leading faculty in education, human resource development, and innovation within the digital industry sector; delivering quality, professionalism, and competitiveness for the 21st century in alignment with the Royal Government\\u2019s Pentagonal Strategy-Phase I, as well as national and international digital economic development. The Faculty aims to produce graduates equipped with comprehensive knowledge, digital skills, creativity, ethics, and practical operational capabilities to effectively compete and respond to the demands of the digital society and future labor markets.<\\\/p><p><br><\\\/p>\",\"km\":\"<p>\\u1780\\u17d2\\u179b\\u17b6\\u1799\\u1787\\u17b6\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u1788\\u17b6\\u1793\\u1798\\u17bb\\u1781\\u1782\\u17c1\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1794\\u17cb\\u179a\\u17c6 \\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1792\\u1793\\u1792\\u17b6\\u1793\\u1798\\u1793\\u17bb\\u179f\\u17d2\\u179f \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u1794\\u1784\\u17d2\\u1780\\u17be\\u178f\\u1790\\u17d2\\u1798\\u17b8\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u17a7\\u179f\\u17d2\\u179f\\u17b6\\u17a0\\u1780\\u1798\\u17d2\\u1798\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u178a\\u17c4\\u1799\\u1795\\u17d2\\u178f\\u179b\\u17cb\\u1793\\u17bc\\u179c\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796 \\u179c\\u17b7\\u1787\\u17d2\\u1787\\u17b6\\u1787\\u17b8\\u179c\\u17c8 \\u1793\\u17b7\\u1784\\u179f\\u1798\\u178f\\u17d2\\u1790\\u1797\\u17b6\\u1796\\u1794\\u17d2\\u179a\\u1780\\u17bd\\u178f\\u1794\\u17d2\\u179a\\u1787\\u17c2\\u1784\\u179f\\u1798\\u17d2\\u179a\\u17b6\\u1794\\u17cb\\u179f\\u178f\\u179c\\u178f\\u17d2\\u179f\\u179a\\u17cd\\u1791\\u17b8\\u17e2\\u17e1 \\u179f\\u17d2\\u179a\\u1794\\u178f\\u17b6\\u1798\\u1799\\u17bb\\u1791\\u17d2\\u1792\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1794\\u1789\\u17d2\\u1785\\u1780\\u17c4\\u178e-\\u178a\\u17c6\\u178e\\u17b6\\u1780\\u17cb\\u1780\\u17b6\\u179b\\u1791\\u17b8\\u17e1 \\u179a\\u1794\\u179f\\u17cb\\u179a\\u17b6\\u1787\\u179a\\u178a\\u17d2\\u178b\\u17b6\\u1797\\u17b7\\u1794\\u17b6\\u179b \\u1780\\u17cf\\u178a\\u17bc\\u1785\\u1787\\u17b6\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u179f\\u17c1\\u178a\\u17d2\\u178b\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u1790\\u17d2\\u1793\\u17b6\\u1780\\u17cb\\u1787\\u17b6\\u178f\\u17b7 \\u1793\\u17b7\\u1784\\u17a2\\u1793\\u17d2\\u178f\\u179a\\u1787\\u17b6\\u178f\\u17b7\\u17d4<\\\/p>\"}},{\"title\":{\"en\":\"Goals and Purpose\",\"km\":\"\\u1782\\u17c4\\u179b\\u178a\\u17c5 \\u1793\\u17b7\\u1784\\u1782\\u17c4\\u179b\\u1794\\u17c6\\u178e\\u1784\"},\"content\":{\"en\":\"<p>The Faculty of Digital Industries is committed to achieving the following goals and purposes:<\\\/p><ol><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Departmental and Major Excellence<\\\/strong>: To provide high-quality, specialized education across its academic departments by producing competent Information Technology professionals, Digital Marketing strategists, Graphic Design and UI\\\/UX specialists, and Social Media professionals who are equipped to meet national and international workforce demands.<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Industry-Oriented Curriculum Development<\\\/strong>: To design and continuously enhance modern, technology-driven curricula that align with industry needs through practical learning approaches, Project-Based Learning (PBL), laboratory practice, and real-world applications.<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Human Capital Development<\\\/strong>: To cultivate highly skilled graduates with strong technical competencies, digital literacy, innovation, leadership, professional ethics, and lifelong learning capabilities that contribute to the digital economy and sustainable national development.<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Research, Innovation, and Entrepreneurship<\\\/strong>: To promote a culture of research, innovation, creativity, and technological development that generates practical digital solutions and encourages entrepreneurship for addressing real-world challenges.<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Faculty and Staff Capacity Development<\\\/strong>: To strengthen the academic, pedagogical, technical, and professional competencies of faculty members and support staff through continuous professional development, research engagement, and industry collaboration.<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Strategic Industry and Institutional Partnerships<\\\/strong>: To establish and expand partnerships with industry, government agencies, professional organizations, and international institutions in order to facilitate internships, collaborative research, knowledge exchange, professional certification, and graduate employment opportunities.<\\\/li><li data-list=\\\"bullet\\\" class=\\\"ql-indent-1\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Quality Assurance and Institutional Excellence<\\\/strong>: To implement comprehensive Internal Quality Assurance (IQA) systems and Standard Operating Procedures (SOPs) that promote academic excellence, transparency, accountability, continuous improvement, and compliance with national accreditation standards.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span><strong>Student Success and Employability<\\\/strong>: To foster an inclusive, student-centered learning environment that develops graduates with critical thinking, problem-solving, communication, teamwork, adaptability, and entrepreneurial skills, enabling them to succeed in an increasingly competitive global digital workforce.<\\\/li><\\\/ol>\",\"km\":\"<p>\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u17a7\\u179f\\u17d2\\u179f\\u17b6\\u17a0\\u1780\\u1798\\u17d2\\u1798\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u1794\\u17d2\\u178f\\u17c1\\u1787\\u17d2\\u1789\\u17b6\\u1785\\u17b7\\u178f\\u17d2\\u178f\\u179f\\u1798\\u17d2\\u179a\\u17c1\\u1785\\u17b1\\u17d2\\u1799\\u1794\\u17b6\\u1793\\u1793\\u17bc\\u179c\\u1782\\u17c4\\u179b\\u178a\\u17c5 \\u1793\\u17b7\\u1784\\u1782\\u17c4\\u179b\\u1794\\u17c6\\u178e\\u1784\\u178a\\u17bc\\u1785\\u1781\\u17b6\\u1784\\u1780\\u17d2\\u179a\\u17c4\\u1798\\u17d6<\\\/p><p><strong>\\u17e1. \\u17a7\\u178f\\u17d2\\u178a\\u1798\\u1797\\u17b6\\u1796\\u178f\\u17b6\\u1798\\u178a\\u17c1\\u1794\\u17c9\\u17b6\\u178f\\u17ba\\u1798\\u17c9\\u1784\\u17cb \\u1793\\u17b7\\u1784\\u1787\\u17c6\\u1793\\u17b6\\u1789 (Departmental and Major Excellence):<\\\/strong> \\u1795\\u17d2\\u178f\\u179b\\u17cb\\u1787\\u17bc\\u1793\\u1793\\u17bc\\u179c\\u1780\\u17b6\\u179a\\u17a2\\u1794\\u17cb\\u179a\\u17c6\\u17af\\u1780\\u1791\\u17c1\\u179f\\u178a\\u17c2\\u179b\\u1798\\u17b6\\u1793\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796\\u1781\\u17d2\\u1796\\u179f\\u17cb\\u1793\\u17c5\\u178f\\u17b6\\u1798\\u1782\\u17d2\\u179a\\u1794\\u17cb\\u178a\\u17c1\\u1794\\u17c9\\u17b6\\u178f\\u17ba\\u1798\\u17c9\\u1784\\u17cb \\u178a\\u17c4\\u1799\\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u179b\\u17a2\\u17d2\\u1793\\u1780\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u1796\\u17d0\\u178f\\u17cc\\u1798\\u17b6\\u1793 \\u17a2\\u17d2\\u1793\\u1780\\u1799\\u17bb\\u1791\\u17d2\\u1792\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1791\\u17b8\\u1795\\u17d2\\u179f\\u17b6\\u179a\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u17a2\\u17d2\\u1793\\u1780\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u179a\\u1785\\u1793\\u17b6\\u1780\\u17d2\\u179a\\u17b6\\u17a0\\u17d2\\u179c\\u17b7\\u1780 \\u1793\\u17b7\\u1784 UI\\\/UX \\u1793\\u17b7\\u1784\\u17a2\\u17d2\\u1793\\u1780\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1795\\u17d2\\u179f\\u1796\\u17d2\\u179c\\u1795\\u17d2\\u179f\\u17b6\\u1799\\u179f\\u1784\\u17d2\\u1782\\u1798\\u178a\\u17c2\\u179b\\u1798\\u17b6\\u1793\\u179f\\u1798\\u178f\\u17d2\\u1790\\u1797\\u17b6\\u1796 \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u1786\\u17d2\\u179b\\u17be\\u1799\\u178f\\u1794\\u1793\\u17b9\\u1784\\u178f\\u1798\\u17d2\\u179a\\u17bc\\u179c\\u1780\\u17b6\\u179a\\u1780\\u1798\\u17d2\\u179b\\u17b6\\u17c6\\u1784\\u1796\\u179b\\u1780\\u1798\\u17d2\\u1798\\u1787\\u17b6\\u178f\\u17b7 \\u1793\\u17b7\\u1784\\u17a2\\u1793\\u17d2\\u178f\\u179a\\u1787\\u17b6\\u178f\\u17b7\\u17d4<\\\/p><p><strong>\\u17e2. \\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1780\\u1798\\u17d2\\u1798\\u179c\\u17b7\\u1792\\u17b8\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u1795\\u17d2\\u17a2\\u17c2\\u1780\\u179b\\u17be\\u17a7\\u179f\\u17d2\\u179f\\u17b6\\u17a0\\u1780\\u1798\\u17d2\\u1798 (Industry-Oriented Curriculum Development):<\\\/strong> \\u179a\\u1785\\u1793\\u17b6 \\u1793\\u17b7\\u1784\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1780\\u1798\\u17d2\\u1798\\u179c\\u17b7\\u1792\\u17b8\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u1791\\u17c6\\u1793\\u17be\\u1794\\u178a\\u17c2\\u179b\\u178a\\u17b9\\u1780\\u1793\\u17b6\\u17c6\\u178a\\u17c4\\u1799\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u1787\\u17b6\\u1794\\u17d2\\u179a\\u1785\\u17b6\\u17c6 \\u17b1\\u17d2\\u1799\\u179f\\u17d2\\u179a\\u1794\\u178f\\u17b6\\u1798\\u178f\\u1798\\u17d2\\u179a\\u17bc\\u179c\\u1780\\u17b6\\u179a\\u17a7\\u179f\\u17d2\\u179f\\u17b6\\u17a0\\u1780\\u1798\\u17d2\\u1798 \\u178f\\u17b6\\u1798\\u179a\\u1799\\u17c8\\u179c\\u17b7\\u1792\\u17b8\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u179a\\u17c0\\u1793\\u178a\\u17c4\\u1799\\u17a2\\u1793\\u17bb\\u179c\\u178f\\u17d2\\u178f\\u1787\\u17b6\\u1780\\u17cb\\u179f\\u17d2\\u178f\\u17c2\\u1784 \\u1780\\u17b6\\u179a\\u179a\\u17c0\\u1793\\u1795\\u17d2\\u17a2\\u17c2\\u1780\\u179b\\u17be\\u1782\\u1798\\u17d2\\u179a\\u17c4\\u1784 (Project-Based Learning - PBL) \\u1780\\u17b6\\u179a\\u17a2\\u1793\\u17bb\\u179c\\u178f\\u17d2\\u178f\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1794\\u1793\\u17d2\\u1791\\u1794\\u17cb\\u1796\\u17b7\\u179f\\u17c4\\u1792\\u1793\\u17cd \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1793\\u17bb\\u179c\\u178f\\u17d2\\u178f\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1796\\u17b7\\u1797\\u1796\\u1796\\u17b7\\u178f\\u17d4<\\\/p><p><strong>\\u17e3. \\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1798\\u17bc\\u179b\\u1792\\u1793\\u1798\\u1793\\u17bb\\u179f\\u17d2\\u179f(Human Capital Development):<\\\/strong> \\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u179b\\u1793\\u17b7\\u179f\\u17d2\\u179f\\u17b7\\u178f\\u1794\\u1789\\u17d2\\u1785\\u1794\\u17cb\\u1780\\u17b6\\u179a\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u17b1\\u17d2\\u1799\\u1798\\u17b6\\u1793\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u1781\\u17d2\\u1796\\u179f\\u17cb \\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u179f\\u1798\\u178f\\u17d2\\u1790\\u1797\\u17b6\\u1796\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u1791\\u17c1\\u179f\\u179a\\u17b9\\u1784\\u1798\\u17b6\\u17c6 \\u1785\\u17c6\\u178e\\u17c1\\u17c7\\u178a\\u17b9\\u1784\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u1780\\u17b6\\u179a\\u1794\\u1784\\u17d2\\u1780\\u17be\\u178f\\u1790\\u17d2\\u1798\\u17b8 \\u1797\\u17b6\\u1796\\u1787\\u17b6\\u17a2\\u17d2\\u1793\\u1780\\u178a\\u17b9\\u1780\\u1793\\u17b6\\u17c6 \\u1780\\u17d2\\u179a\\u1798\\u179f\\u17b8\\u179b\\u1792\\u1798\\u17cc\\u179c\\u17b7\\u1787\\u17d2\\u1787\\u17b6\\u1787\\u17b8\\u179c\\u17c8 \\u1793\\u17b7\\u1784\\u179f\\u1798\\u178f\\u17d2\\u1790\\u1797\\u17b6\\u1796\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u1796\\u17c1\\u1789\\u1798\\u17bd\\u1799\\u1787\\u17b8\\u179c\\u17b7\\u178f \\u178a\\u17c2\\u179b\\u179a\\u17bd\\u1798\\u1785\\u17c6\\u178e\\u17c2\\u1780\\u178a\\u179b\\u17cb\\u179f\\u17c1\\u178a\\u17d2\\u178b\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u