4\\u17a7\\u178f\\u17d2\\u178a\\u1798\\u1797\\u17b6\\u1796\\u179f\\u17d2\\u1790\\u17b6\\u1794\\u17d0\\u1793 (Quality Assurance and Institutional Excellence):<\\\/strong>\\u17a2\\u1793\\u17bb\\u179c\\u178f\\u17d2\\u178f\\u1794\\u17d2\\u179a\\u1796\\u17d0\\u1793\\u17d2\\u1792\\u1792\\u17b6\\u1793\\u17b6\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796\\u1795\\u17d2\\u1791\\u17c3\\u1780\\u17d2\\u1793\\u17bb\\u1784 (IQA) \\u1793\\u17b7\\u1784\\u1793\\u17b8\\u178f\\u17b7\\u179c\\u17b7\\u1792\\u17b8\\u1794\\u17d2\\u179a\\u178f\\u17b7\\u1794\\u178f\\u17d2\\u178f\\u17b7\\u179f\\u17d2\\u178f\\u1784\\u17cb\\u178a\\u17b6\\u179a (SOPs) \\u17b1\\u17d2\\u1799\\u1794\\u17b6\\u1793\\u1782\\u17d2\\u179a\\u1794\\u17cb\\u1787\\u17d2\\u179a\\u17bb\\u1784\\u1787\\u17d2\\u179a\\u17c4\\u1799 \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u179b\\u17be\\u1780\\u1780\\u1798\\u17d2\\u1796\\u179f\\u17cb\\u17a7\\u178f\\u17d2\\u178a\\u1798\\u1797\\u17b6\\u1796\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6 \\u178f\\u1798\\u17d2\\u179b\\u17b6\\u1797\\u17b6\\u1796 \\u1782\\u178e\\u1793\\u17c1\\u1799\\u17d2\\u1799\\u1797\\u17b6\\u1796 \\u1780\\u17b6\\u179a\\u1780\\u17c2\\u179b\\u1798\\u17d2\\u17a2\\u1787\\u17b6\\u1794\\u17d2\\u179a\\u1785\\u17b6\\u17c6 \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1793\\u17bb\\u179b\\u17c4\\u1798\\u178f\\u17b6\\u1798\\u179f\\u17d2\\u178f\\u1784\\u17cb\\u178a\\u17b6\\u179a\\u1782\\u17bb\\u178e\\u179c\\u17bb\\u178c\\u17d2\\u178d\\u17b7\\u17a2\\u1794\\u17cb\\u179a\\u17c6\\u1787\\u17b6\\u178f\\u17b7\\u17d4<\\\/p><p><strong>\\u17e8. \\u1787\\u17c4\\u1782\\u1787\\u17d0\\u1799 \\u1793\\u17b7\\u1784\\u17b1\\u1780\\u17b6\\u179f\\u1780\\u17b6\\u179a\\u1784\\u17b6\\u179a\\u179a\\u1794\\u179f\\u17cb\\u1793\\u17b7\\u179f\\u17d2\\u179f\\u17b7\\u178f (Student Success and Employability):<\\\/strong> \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u179b\\u17be\\u1780\\u1780\\u1798\\u17d2\\u1796\\u179f\\u17cb\\u1794\\u179a\\u17b7\\u179f\\u17d2\\u1790\\u17b6\\u1793\\u179f\\u17b7\\u1780\\u17d2\\u17