            'custom_sections' => '[{\"title\":{\"en\":\"About the Faculty\",\"km\":\"\\u17a2\\u17c6\\u1796\\u17b8\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\"},\"content\":{\"en\":\"<p>The Faculty of English Language at Digital University of Cambodia (DUC) is dedicated to providing high-quality English language education that prepares students for academic excellence, professional success, and lifelong learning. The Faculty equips students with strong English communication skills, digital competencies, critical thinking, research abilities, and leadership qualities to meet the demands of the 21st-century global workforce.<\\\/p><p>Through innovative teaching methods, modern technology, and practical learning experiences, the Faculty develops graduates who are competent, ethical, creative, and ready to contribute to Cambodia's socio-economic development and the digital economy.<\\\/p>\",\"km\":\"<p>\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u1797\\u17b6\\u179f\\u17b6\\u17a2\\u1784\\u17cb\\u1782\\u17d2\\u179b\\u17c1\\u179f \\u1793\\u17c3\\u179f\\u17b6\\u1780\\u179b\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u1780\\u1798\\u17d2\\u1796\\u17bb\\u1787\\u17b6 (DUC) \\u1794\\u17d2\\u178f\\u17c1\\u1787\\u17d2\\u1789\\u17b6\\u1795\\u17d2\\u178f\\u179b\\u17cb\\u1780\\u17b6\\u179a\\u17a2\\u1794\\u17cb\\u179a\\u17c6\\u1797\\u17b6\\u179f\\u17b6\\u17a2\\u1784\\u17cb\\u1782\\u17d2\\u179b\\u17c1\\u179f\\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796\\u1781\\u17d2\\u1796\\u179f\\u17cb \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u179a\\u17c0\\u1794\\u1785\\u17c6\\u1793\\u17b7\\u179f\\u17d2\\u179f\\u17b7\\u178f\\u17b1\\u17d2\\u1799\\u1791\\u1791\\u17bd\\u179b\\u1794\\u17b6\\u1793\\u1797\\u17b6\\u1796\\u1787\\u17c4\\u1782\\u1787\\u17d0\\u1799\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1780\\u17b6\\u