17b6\\u1798\\u179a\\u1799\\u17c8\\u1780\\u17b6\\u179a\\u1796\\u1784\\u17d2\\u179a\\u17b9\\u1784 \\u1793\\u17b7\\u1784\\u1796\\u1784\\u17d2\\u179a\\u17b9\\u1780 \\u179f\\u1780\\u17d2\\u178f\\u17b6\\u1793\\u17bb\\u1796\\u179b\\u1795\\u179b\\u17b7\\u178f\\u1797\\u17b6\\u1796\\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798 \\u1780\\u17b6\\u179a\\u1792\\u17b6\\u1793\\u17b6\\u179f\\u17bb\\u179c\\u178f\\u17d2\\u1790\\u17b7\\u1797\\u17b6\\u1796\\u179f\\u17d2\\u1794\\u17c0\\u1784 \\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179a\\u1780\\u17d2\\u179f\\u1792\\u1793\\u1792\\u17b6\\u1793\\u1792\\u1798\\u17d2\\u1798\\u1787\\u17b6\\u178f\\u17b7 \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u179f\\u1784\\u17d2\\u1782\\u1798\\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1785\\u17b8\\u179a\\u1797\\u17b6\\u1796\\u17d4<\\\/p><p class=\\\"ql-align-justify\\\">\\u1780\\u1798\\u17d2\\u1798\\u179c\\u17b7\\u1792\\u17b8\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u179a\\u17bd\\u1798\\u1794\\u1789\\u17d2\\u1785\\u17bc\\u179b\\u1791\\u17b6\\u17c6\\u1784\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798 \\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b (Digital Agriculture) \\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798\\u1786\\u17d2\\u179b\\u17b6\\u178f\\u179c\\u17c3 (Smart Agriculture) \\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798\\u1787\\u17b6\\u1780\\u17cb\\u179b\\u17b6\\u1780\\u17cb (Precision Agriculture) \\u1796\\u17d0\\u178f\\u17cc\\u1798\\u17b6\\u1793\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u1793\\u17c3\\u179c\\u178f\\u17d2\\u1790\\u17bb (IoT) \\u179f\\u17a0\\u1782\\u17d2\\u179a\\u17b7\\u1793\\u1797\\u17b6\\u1796 \\u1780\\u17b6\\u179a\\u1782\\u17d2\\u179a\\u1794\\u17cb\\u1782\\u17d2\\u179a\\u1784\\u1792\\u17bb\\u179a\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798 \\u1793\\u17b7\\u1784\\u1798\\u17b6\\u1793\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u179f\\u17a0\\u1794\\u17d2\\u179a\\u178f\\u17b7\\u1794\\u178f\\u17d2\\u178f\\u17b7\\u1780\\u17b6\\u179a\\u1787\\u17b6\\u1798\\u17bd\\u1799\\u179f\\u17d2\\u1790\\u17b6\\u1794\\u17d0\\u1793\\u179a\\u178a\\u17d2\\u178b \\u179c\\u17b7\\u179f\\u17d0\\u1799\\u17af\\u1780\\u1787\\u1793 \\u17a2\\u1784\\u17d2\\u1782\\u1780\\u17b6\\u179a\\u1780\\u17d2\\u179a\\u17c5\\u179a\\u178a\\u17d2\\u178b\\u17b6\\u1797\\u17b7\\u1794\\u17b6\\u179b\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u1794\\u17b6\\u1793\\u1794\\u17d2\\u178f\\u17c1\\u1787\\u17d2\\u1789\\u17b6\\u1785\\u17b7\\u178f\\u17d2\\u178f\\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1793\\u17b7\\u1784\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1793\\u17b7\\u179f\\u17d2\\u179f\\u17b7\\u178f\\u17b1\\u17d2\\u1799\\u1798\\u17b6\\u1793\\u179f\\u1798\\u178f\\u17d2\\u1790\\u1797\\u17b6\\u1796\\u1786\\u17d2\\u179b\\u17be\\u1799\\u178f\\u1794\\u1791\\u17c5\\u1793\\u17b9\\u1784\\u178f\\u1798\\u17d2\\u179a\\u17bc\\u179c\\u1780\\u17b6\\u179a\\u1791\\u17b8\\u1795\\u17d2\\u179f\\u17b6\\u179a\\u1780\\u17b6\\u179a\\u1784\\u17b6\\u179a \\u1793\\u17b7\\u1784\\u179a\\u17bd\\u1798\\u1785\\u17c6\\u178e\\u17c2\\u1780\\u178a\\u179b\\u17cb\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u179f\\u17c1\\u178a\\u17d2\\u178b\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u1780\\u1798\\u17d2\\u1796\\u17bb\\u1787\\u17b6\\u17d4<\\\/p>\"}},{\"title\":{\"en\":\"Vision\",\"km\":\"\\u1785\\u1780\\u17d2\\u1781\\u17bb\\u179c\\u17b7\\u179f\\u17d0\\u1799\"},\"content\":{\"en\":\"<p>To become a center of excellence in education recognized for its national standards and innovative approach in agriculture and rural development, producing highly ethical human resources with technical expertise and the ability to leverage modern technology to transform Cambodia's agricultural sector into smart agriculture and drive national economic growth in the digital era.<\\\/p>\",\"km\":\"<p class=\\\"ql-align-justify\\\"><span style=\\\"color: windowtext;\\\">\\u1780\\u17d2\\u179b\\u17b6\\u1799\\u1787\\u17b6\\u1798\\u1787\\u17d2\\u1788\\u1798\\u178e\\u17d2\\u178c\\u179b\\u17a7\\u178f\\u17d2\\u178f\\u1798\\u1797\\u17b6\\u1796\\u1793\\u17c3\\u1780\\u17b6\\u179a\\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u179b\\u178a\\u17c2\\u179b\\u1791\\u1791\\u17bd\\u179b\\u179f\\u17d2\\u1782\\u17b6\\u179b\\u17cb\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796\\u17a2\\u1794\\u17cb\\u179a\\u17c6\\u178f\\u17b6\\u1798\\u179f\\u17d2\\u178f\\u1784\\u17cb\\u178a\\u17b6\\u179a\\u1787\\u17b6\\u178f\\u17b7 \\u1793\\u17b7\\u1784\\u1798\\u17b6\\u1793\\u1782\\u17c6\\u1793\\u17b7\\u178f\\u1785\\u17d2\\u1793\\u17c3\\u1794\\u17d2\\u179a\\u178c\\u17b7\\u178f\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798 \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1787\\u1793\\u1794\\u1791 \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u1795\\u179b\\u17b7\\u178f\\u1794\\u17b6\\u1793\\u1793\\u17bc\\u179c\\u1798\\u17bc\\u179b\\u1792\\u1793\\u1792\\u17b6\\u1793\\u1798\\u1793\\u17bb\\u179f\\u17d2\\u179f\\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1780\\u17d2\\u179a\\u1798\\u179f\\u17b8\\u179b\\u1792\\u1798\\u17cc\\u179c\\u17b7\\u1787\\u17d2\\u1787\\u17b6\\u1787\\u17b8\\u179c\\u17c8\\u1798\\u17b6\\u1793\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u1791\\u17c1\\u179f \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u1794\\u17d2\\u179a\\u17be\\u1794\\u17d2\\u179a\\u17b6\\u179f\\u17cb\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u1791\\u17c6\\u1793\\u17be\\u1794 \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u1794\\u17c6\\u1794\\u17d2\\u179b\\u17c2\\u1784\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798\\u1780\\u1798\\u17d2\\u1796\\u17bb\\u1787\\u17b6\\u1791\\u17c5\\u1787\\u17b6\\u1780\\u179f\\u17b7\\u1780\\u1798\\u17d2\\u1798\\u179c\\u17c3\\u1786\\u17d2\\u179b\\u17b6\\u178f (Smart Agriculture) \\u1793\\u17b7\\u1784\\u1787\\u17c6\\u179a\\u17bb\\u1789\\u1780\\u17c6\\u178e\\u17be\\u1793\\u179f\\u17c1\\u178a\\u17d2\\u178b\\u1780\\u17b7\\u1785\\u17d2\\u1785\\u1787\\u17b6\\u178f\\u17b7\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1799\\u17bb\\u1782\\u179f\\u1798\\u17d0\\u1799\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u17d4<\\\/span><\\\/p>\"}},{\"title\":{\"en\":\"Mission\",\"km\":\"\\u1794\\u17c1\\u179f\\u1780\\u1780\\u1798\\u17d2\\u1798\"},\"content\":{\"en\":\"<p>The faculty has the following missions:<\\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Provide high-quality education in the fields of agriculture and rural development.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Train students to acquire knowledge, skills, experience, and professional ethics.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Promote research, innovation, and the integration of digital technology in agriculture.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Strengthen partnerships with public, private, community, and development partners.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Provide professional services and technology transfers to farmers, communities, and enterprises.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Support the development of green agriculture, smart agriculture, and sustainable rural development.<\\\/li><\\\/ol>\",\"km\":\"<p>\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u1