            'custom_sections' => '[{\"title\":{\"en\":\"About the Faculty\",\"km\":\"\\u17a2\\u17c6\\u1796\\u17b8\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\"},\"content\":{\"en\":\"<p>The Faculty of Law and Political Science (FLPS) is a vital executive entity leading and coordinating specialized training programs, which serve as the strategic educational direction of the Digital University of Cambodia. The Faculty (FLPS) has a mission to train high-level human resources and promote research in law, public policy, political science, diplomacy, and digital field to serve social interests and sustainable national development, with the ultimate goal of transforming into a renowned center of excellence at both national and international levels.<\\\/p>\",\"km\":\"<p>\\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u1793\\u17b8\\u178f\\u17b7\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a \\u1793\\u17b7\\u1784\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1793\\u1799\\u17c4\\u1794\\u17b6\\u1799 (\\u1798.\\u1793.\\u179c) \\u1782\\u17ba\\u1787\\u17b6\\u17a2\\u1784\\u17d2\\u1782\\u1797\\u17b6\\u1796\\u179f\\u17c1\\u1793\\u17b6\\u1792\\u17b7\\u1780\\u17b6\\u179a\\u178a\\u17cf\\u179f\\u17c6\\u1781\\u17b6\\u1793\\u17cb \\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1780\\u17b6\\u179a\\u178a\\u17b9\\u1780\\u1793\\u17b6\\u17c6 \\u1793\\u17b7\\u1784\\u179f\\u1798\\u17d2\\u179a\\u1794\\u179f\\u1798\\u17d2\\u179a\\u17bd\\u179b\\u1780\\u1798\\u17d2\\u1798\\u179c\\u17b7\\u1792\\u17b8\\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u179b\\u17af\\u1780\\u1791\\u17c1\\u179f \\u178a\\u17c2\\u179b\\u1787\\u17b6\\u1791\\u17b7\\u179f\\u178a\\u17c5\\u17a2\\u1794\\u17cb\\u179a\\u17c6\\u1799\\u17bb\\u1791\\u17d2\\u1792\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u179a\\u1794\\u179f\\u17cb\\u179f\\u17b6\\u1780\\u179b\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u1780\\u1798\\u17d2\\u1796\\u17bb\\u1787\\u17b6\\u17d4 \\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799(\\u1798.\\u1793.\\u179c) \\u1798\\u17b6\\u1793\\u1794\\u17c1\\u179f\\u1780\\u1780\\u1798\\u17d2\\u1798\\u1794\\u178e\\u17d2\\u178f\\u17bb\\u17c7\\u1794\\u178e\\u17d2\\u178f\\u17b6\\u179b\\u1792\\u1793\\u1792\\u17b6\\u1793\\u1798\\u1793\\u17bb\\u179f\\u17d2\\u179f\\u1780\\u1798\\u17d2\\u179a\\u17b7\\u178f\\u1781\\u17d2\\u1796\\u179f\\u17cb \\u1793\\u17b7\\u1784\\u1787\\u17c6\\u179a\\u17bb\\u1789\\u1780\\u17b6\\u179a\\u179f\\u17d2\\u179a\\u17b6\\u179c\\u1787\\u17d2\\u179a\\u17b6\\u179c\\u179b\\u17be\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u1785\\u17d2\\u1794\\u17b6\\u1794\\u17cb \\u1782\\u17c4\\u179b\\u1793\\u1799\\u17c4\\u1794\\u17b6\\u1799\\u179f\\u17b6\\u1792\\u17b6\\u179a\\u178e\\u17c8 \\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1793\\u1799\\u17c4\\u1794\\u17b6\\u1799 \\u1780\\u17b6\\u179a\\u1791\\u17bc\\u178f \\u1793\\u17b7\\u1784\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u1794\\u1798\\u17d2\\u179a\\u17be\\u1795\\u179b\\u1794\\u17d2\\u179a\\u1799\\u17c4\\u1787\\u1793\\u17cd\\u179f\\u1784\\u17d2\\u1782\\u1798 \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u1787\\u17b6\\u178f\\u17b7\\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1785\\u17b8\\u179a\\u1797\\u17b6\\u1796 \\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1782\\u17c4\\u179b\\u178a\\u17c5\\u1794\\u17d2\\u179a\\u17c2\\u1780\\u17d2\\u179b\\u17b6\\u1799\\u1781\\u17d2\\u179b\\u17bd\\u1793\\u1787\\u17b6\\u1798\\u1787\\u17d2\\u1788\\u1798\\u178e\\u17d2\\u178c\\u179b\\u17a7\\u178f\\u17d2\\u178f\\u1798\\u1797\\u17b6\\u1796 \\u178a\\u17c2\\u179b\\u1798\\u17b6\\u1793\\u1780\\u17c1\\u179a\\u17d2\\u178f\\u17b7\\u17cd\\u1788\\u17d2\\u1798\\u17c4\\u17c7\\u179b\\u17d2\\u1794\\u17b8\\u179b\\u17d2\\u1794\\u17b6\\u1789\\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1780\\u1798\\u17d2\\u179a\\u17b7\\u178f\\u1787\\u17b6\\u178f\\u17b7 \\u1793\\u17b7\\u1784\\u17a2\\u1793\\u17d2\\u178f\\u179a\\u1787\\u17b6\\u178f\\u17b7\\u17d4<\\\/p>\"}},{\"title\":{\"en\":\"Vision\",\"km\":\"\\u1785\\u1780\\u17d2\\u1781\\u17bb\\u179c\\u17b7\\u179f\\u17d0\\u1799\"},\"content\":{\"en\":\"<p>To be a center of educational excellence in building human capital, focusing on digital youth equipped with intellect and high professional ethics to contribute to strengthening the rule of law, social justice, and lasting peace.<\\\/p>\",\"km\":\"<p>\\u1787\\u17b6\\u1798\\u1787\\u17d2\\u1788\\u1798\\u178e\\u17d2\\u178c\\u179b\\u17a7\\u178f\\u17d2\\u178f\\u1798\\u1797\\u17b6\\u1796\\u1793\\u17c3\\u1780\\u17b6\\u179a\\u17a2\\u1794\\u17cb\\u179a\\u17c6 \\u1780\\u17d2\\u1793\\u17bb\\u1784\\u1780\\u17b6\\u179a\\u1780\\u179f\\u17b6\\u1784\\u1798\\u17bc\\u179b\\u1792\\u1793\\u1798\\u1793\\u17bb\\u179f\\u17d2\\u179f \\u178a\\u17c4\\u1799\\u1795\\u17d2\\u178f\\u17c4\\u178f\\u179b\\u17be\\u1799\\u17bb\\u179c\\u1787\\u1793\\u178c\\u17b8\\u1787\\u17b8\\u1790\\u179b\\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1794\\u1789\\u17d2\\u1789\\u17b6\\u1789\\u17b6\\u178e \\u1793\\u17b7\\u1784\\u1798\\u1793\\u179f\\u17b7\\u1780\\u17b6\\u179a\\u179c\\u17b7\\u1787\\u17d2\\u1787\\u17b6\\u1787\\u17b8\\u179c\\u17c8\\u1781\\u17d2\\u1796\\u179f\\u17cb \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u179a\\u17bd\\u1798\\u1785\\u17c6\\u178e\\u17c2\\u1780\\u1796\\u1784\\u17d2\\u179a\\u17b9\\u1784\\u1793\\u17b8\\u178f\\u17b7\\u179a\\u178a\\u17d2\\u178b \\u1799\\u17bb\\u178f\\u17d2\\u178f\\u17b7\\u1792\\u1798\\u17cc\\u179f\\u1784\\u17d2\\u1782\\u1798 \\u1793\\u17b7\\u1784\\u179f\\u1793\\u17d2\\u178f\\u17b7\\u1797\\u17b6\\u1796\\u1787\\u17b6\\u1793\\u17b7\\u179a\\u1793\\u17d2\\u178f\\u179a\\u17cd\\u17d4<\\\/p>\"}},{\"title\":{\"en\":\"Mission\",\"km\":\"\\u1794\\u17c1\\u179f\\u1780\\u1780\\u1798\\u17d2\\u1798\"},\"content\":{\"en\":\"<p>To achieve the above vision, the Faculty has outlined the following key missions:<\\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Provide high-quality higher education in law, political science, and diplomacy aligned with national and international standards to meet the demands of the labor market and socio-economic development in the digital age.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Promote scientific research in law, politics, and international relations to contribute to solving social issues and formulating public policy.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Cultivate moral values, virtue, and high professional responsibility in students to ensure they become clean legal practitioners and political leaders imbued with modern entrepreneurship.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Participate in disseminating legal and political knowledge to the public to enhance awareness of rights, freedoms, and duties as good citizens in a democratic society under the framework of law.<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>Expand relationships and cooperation with state institutions, the private sector, civil society organizations, and international partners to exchange experiences and strengthen scientific research capabilities.<\\\/li><\\\/ol>\",\"km\":\"<p>\\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u179f\\u1798\\u17d2\\u179a\\u17c1\\u1785\\u1794\\u17b6\\u1793\\u1793\\u17bc\\u179c\\u1785\\u1780\\u17d2\\u1781\\u17bb\\u179c\\u17b7\\u179f\\u17d0\\u1799\\u1781\\u17b6\\u1784\\u179b\\u17be \\u1798\\u17a0\\u17b6\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179b\\u17d0\\u1799\\u1794\\u17b6\\u1793\\u1780\\u17c6\\u178e\\u178f\\u17cb\\u1794\\u17c1\\u179f\\u1780\\u1780\\u1798\\u17d2\\u1798\\u179f\\u17c6\\u1781\\u17b6\\u1793\\u17cb\\u17d7 \\u178a\\u17bc\\u1785\\u1781\\u17b6\\u1784\\u1780\\u17d2\\u179a\\u17c4\\u1798\\u17d6<\\\/p><ol><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>\\u1795\\u17d2\\u178f\\u179b\\u17cb\\u1780\\u17b6\\u179a\\u17a2\\u1794\\u17cb\\u179a\\u17c6\\u1780\\u1798\\u17d2\\u179a\\u17b7\\u178f\\u17a7\\u178f\\u17d2\\u178f\\u1798\\u179f\\u17b7\\u1780\\u17d2\\u179f\\u17b6\\u179b\\u17be\\u1787\\u17c6\\u1793\\u17b6\\u1789\\u1785\\u17d2\\u1794\\u17b6\\u1794\\u17cb \\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u179f\\u17b6\\u179f\\u17d2\\u178f\\u17d2\\u179a\\u1793\\u1799\\u17c4\\u1794\\u17b6\\u1799 \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u1791\\u17bc\\u178f \\u1794\\u17d2\\u179a\\u1780\\u1794\\u178a\\u17c4\\u1799\\u1782\\u17bb\\u178e\\u1797\\u17b6\\u1796\\u1781\\u17d2\\u1796\\u179f\\u17cb \\u179f\\u17d2\\u179a\\u1794\\u178f\\u17b6\\u1798\\u179f\\u17d2\\u178f\\u1784\\u17cb\\u178a\\u17b6\\u179a\\u1787\\u17b6\\u178f\\u17b7-\\u17a2\\u1793\\u17d2\\u178f\\u179a\\u1787\\u17b6\\u178f\\u17b7 \\u178a\\u17be\\u1798\\u17d2\\u1794\\u17b8\\u1786\\u17d2\\u179b\\u17be\\u1799\\u178f\\u1794\\u1791\\u17c5\\u1793\\u17b9\\u1784\\u178f\\u1798\\u17d2\\u179a\\u17bc\\u179c\\u1780\\u17b6\\u179a\\u1791\\u17b8\\u1795\\u17d2\\u179f\\u17b6\\u179a\\u1780\\u17b6\\u179a\\u1784\\u17b6\\u179a \\u1793\\u17b7\\u1784\\u1780\\u17b6\\u179a\\u17a2\\u1797\\u17b7\\u179c\\u178c\\u17d2\\u178d\\u179f\\u1784\\u17d2\\u1782\\u1798-\\u179f\\u17c1\\u178a\\u17d2\\u178b\\u1780\\u17b7\\u1785\\u17d2\\u1785 \\u1780\\u17d2\\u1793\\u17bb\\u1784\\u179f\\u1798\\u17d0\\u1799\\u1794\\u1785\\u17d2\\u1785\\u17c1\\u1780\\u179c\\u17b7\\u1791\\u17d2\\u1799\\u17b6\\u17d4<\\\/li><li data-list=\\\"bullet\\\"><span class=\\\"ql-ui\\\" contenteditable=\\\"false\\\"><\\\/span>\\u179b\\u17be\\u1780\\u1780\\u1798\\u17d2\\u1796\\u179f\\u17cb\\u1780\\u17b6\\u179a\\u179f\\u17d2\\u179a\\u17b6\\u179c\\u1787\\u17d2\\u179a\\u17b6\\u